{"tool":"sandbox","code":"use std::fs;
use std::time::Instant;

const N: usize = 30_000_000;
const SEED: u64 = 0x243F_6A88_85A3_08D3;

struct SplitMix64 {
    state: u64,
}

impl SplitMix64 {
    fn new(seed: u64) -> Self {
        SplitMix64 { state: seed }
    }

    #[inline]
    fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }
}

fn main() {
    let t0 = Instant::now();
    assert_eq!(N, 30_000_000, "unexpected N");
    assert_eq!(N / 2 - 1, 14_999_999, "median low index");
    assert_eq!(N / 2, 15_000_000, "median high index");

    // 1) Generate N seeded pseudo-random u64 values (SplitMix64, fixed seed).
    let mut rng = SplitMix64::new(SEED);
    let mut original: Vec<u64> = Vec::with_capacity(N);
    for _ in 0..N {
        original.push(rng.next_u64());
    }
    assert_eq!(original.len(), N, "generation length mismatch");
    let t_gen = t0.elapsed();

    // 2) Clone and sort the clone in place; both stay in memory (~458 MiB total).
    let mut sorted: Vec<u64> = original.clone();
    assert_eq!(sorted.len(), N, "clone length mismatch");
    sorted.sort_unstable();
    let t_sorted = t0.elapsed();

    // 3) Verify permutation via wrapping sum + xor; check non-decreasing.
    let mut original_sum: u64 = 0;
    let mut original_xor: u64 = 0;
    for &v in original.iter() {
        original_sum = original_sum.wrapping_add(v);
        original_xor ^= v;
    }

    let mut sorted_sum: u64 = 0;
    let mut sorted_xor: u64 = 0;
    let mut prev: u64 = 0;
    for (i, &v) in sorted.iter().enumerate() {
        if i > 0 {
            assert!(
                prev <= v,
                "sorted vector not non-decreasing at index {} ({} > {})",
                i,
                prev,
                v
            );
        }
        sorted_sum = sorted_sum.wrapping_add(v);
        sorted_xor ^= v;
        prev = v;
    }

    assert_eq!(
        original_sum, sorted_sum,
        "wrapping sums differ; permutation check failed"
    );
    assert_eq!(
        original_xor, sorted_xor,
        "xors differ; permutation check failed"
    );
    let t_verified = t0.elapsed();

    // 4) Min, max, median (f64 mean of elements at indices 14,999,999 and 15,000,000).
    let min = sorted[0];
    let max = sorted[N - 1];
    let mid_lo = sorted[N / 2 - 1];
    let mid_hi = sorted[N / 2];
    let median = ((mid_lo as u128 + mid_hi as u128) as f64) / 2.0;

    // 5) Write /work/artifacts/result.json (create parent dirs first).
    let median_str = format!("{:?}", median);
    let mut json = String::with_capacity(512);
    json.push_str("{\"count\":30000000");
    json.push_str(&format!(",\"seed\":{}", SEED));
    json.push_str(&format!(",\"min\":{}", min));
    json.push_str(&format!(",\"max\":{}", max));
    json.push_str(&format!(",\"median\":{}", median_str));
    json.push_str(&format!(",\"sum\":{}", original_sum));
    json.push_str(&format!(",\"xor\":{}", original_xor));
    json.push_str(",\"permutation_verified\":true");
    json.push('}');

    let dir = "/work/artifacts";
    fs::create_dir_all(dir).expect("failed to create /work/artifacts");
    let path = "/work/artifacts/result.json";
    fs::write(path, json.as_bytes()).expect("failed to write result.json");

    // Validate the artifact by reading it back.
    let readback = fs::read_to_string(path).expect("failed to read back result.json");
    assert_eq!(readback, json, "readback content mismatch");
    assert!(readback.contains("\"count\":30000000"), "count field missing");
    assert!(
        readback.contains("\"permutation_verified\":true"),
        "permutation_verified field missing"
    );

    let total = t0.elapsed();
    println!(
        "OK n={} seed={:#018x} min={} max={} median={} sum={} xor={} permutation_verified=true",
        N, SEED, min, max, median_str, original_sum, original_xor
    );
    println!(
        "wrote {} ({} bytes) | gen={:?} sort={:?} verify={:?} total={:?}",
        path,
        json.len(),
        t_gen,
        t_sorted - t_gen,
        t_verified - t_sorted,
        total
    );
}
